class Solution {public int[] solve(int[][] grid){int rows=grid.length,cols=rows==0?0:grid[0].length;int[] out=new int[rows*cols];int used=0,top=0,bottom=rows-1,left=0,right=cols-1;while(top<=bottom&&left<=right){for(int c=left;c<=right;c++)out[used++]=grid[top][c];top++;for(int r=top;r<=bottom;r++)out[used++]=grid[r][right];right--;if(top<=bottom){for(int c=right;c>=left;c--)out[used++]=grid[bottom][c];bottom--;}if(left<=right){for(int r=bottom;r>=top;r--)out[used++]=grid[r][left];left++;}}return out;}}